import { MinimalChatAgentScreen } from "@/components/minimal-chat-agent/minimal-chat-agent-screen";

export const dynamic = "force-dynamic";

export default function MinimalChatAgentPage() {
  return <MinimalChatAgentScreen />;
}

import { handleMinimalChatAgentRequest } from "@/lib/minimal-chat-agent/runtime";

export const runtime = "nodejs";

export async function POST(request: Request) {
  return handleMinimalChatAgentRequest(request);
}

import { TooltipProvider } from "@/components/ui/tooltip";

import { DemoWorkspaceShell } from "@/components/demo-workspace-shell";

import { getMinimalChatAgentRuntimeState } from "@/lib/minimal-chat-agent/runtime";
import { MinimalChatAgentWorkspace } from "@/components/minimal-chat-agent/minimal-chat-agent-workspace";

export function MinimalChatAgentScreen() {
  const runtimeState = getMinimalChatAgentRuntimeState();

  return (
    <TooltipProvider>
      <DemoWorkspaceShell
        badges={[runtimeState.statusLabel, runtimeState.chatModel]}
        breadcrumbClassName="font-heading text-xs tracking-[0.16em]"
        breadcrumbTitle="Minimal Chat Agent"
        headerFrame="card"
        summary="A source-backed minimal agent that combines hosted web search, a public GitHub repository tool, and a client-rendered questionnaire whose answers resume the same AI SDK tool loop."
        title="A minimal agent that knows when to search, inspect, or ask"
      >
        <MinimalChatAgentWorkspace
          chatModel={runtimeState.chatModel}
          isChatAvailable={runtimeState.isChatAvailable}
          nodeVersion={runtimeState.nodeVersion}
          setupMessage={runtimeState.setupMessage}
        />
      </DemoWorkspaceShell>
    </TooltipProvider>
  );
}

"use client";

import {
  Conversation,
  ConversationContent,
  ConversationEmptyState,
  ConversationScrollButton,
} from "@/components/ai-elements/conversation";
import {
  Message,
  MessageContent,
  MessageResponse,
} from "@/components/ai-elements/message";
import {
  PromptInput,
  PromptInputBody,
  PromptInputFooter,
  PromptInputSubmit,
  PromptInputTextarea,
} from "@/components/ai-elements/prompt-input";
import {
  Reasoning,
  ReasoningContent,
  ReasoningTrigger,
} from "@/components/ai-elements/reasoning";
import {
  Source,
  Sources,
  SourcesContent,
  SourcesTrigger,
} from "@/components/ai-elements/sources";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { cn } from "@/lib/utils";
import {
  BotIcon,
  CheckCircle2Icon,
  CircleDotDashedIcon,
  GitForkIcon,
  MessageCircleQuestionIcon,
  RefreshCwIcon,
  SearchIcon,
  SquareIcon,
  StarIcon,
  WorkflowIcon,
} from "lucide-react";

import {
  ConversationErrorMessage,
  useConversationErrorRetry,
} from "@/components/demo-chat/conversation-error-message";

import type { AskUserOutput } from "@/lib/minimal-chat-agent/tools";
import { AskUserCard } from "@/components/minimal-chat-agent/ask-user-card";
import {
  findPendingAskUserPart,
  type ProjectedAskUserPart,
  type ProjectedGithubRepoPart,
  type ProjectedWebSearchPart,
  projectMinimalChatAgentMessage,
} from "@/components/minimal-chat-agent/message-parts";
import { useMinimalChatAgent } from "@/components/minimal-chat-agent/use-minimal-chat-agent";

const samplePrompts = [
  "Look up shadcn-ui/chatbot-template on GitHub and explain what makes it a minimal agent.",
  "Search the web for current human-in-the-loop chat UI patterns and cite the sources.",
  "Help me choose an agent starter. Ask me clarifying questions before you recommend one.",
] as const;

function getToolStatusLabel(state: string) {
  if (state === "output-available") {
    return "Completed";
  }
  if (state === "output-error") {
    return "Failed";
  }
  if (state === "input-available") {
    return "Waiting";
  }
  return "Running";
}

function ToolStatusBadge({ state }: { state: string }) {
  const isCompleted = state === "output-available";

  return (
    <Badge className="gap-1" variant="outline">
      {isCompleted ? (
        <CheckCircle2Icon className="size-3 text-primary" />
      ) : (
        <CircleDotDashedIcon className="size-3 text-muted-foreground" />
      )}
      {getToolStatusLabel(state)}
    </Badge>
  );
}

function WebSearchCard({ part }: { part: ProjectedWebSearchPart }) {
  return (
    <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border bg-muted/25 px-3 py-2.5">
      <div className="flex items-center gap-2">
        <span className="grid size-8 place-items-center rounded-md border bg-background">
          <SearchIcon className="size-4" />
        </span>
        <div>
          <p className="font-medium text-sm">Provider-native web search</p>
          <p className="text-muted-foreground text-xs">
            Retrieval runs inside the model provider.
          </p>
        </div>
      </div>
      <ToolStatusBadge state={part.state} />
    </div>
  );
}

function GithubRepoCard({ part }: { part: ProjectedGithubRepoPart }) {
  const result = part.output && "repo" in part.output ? part.output : null;
  const errorMessage =
    part.output && "error" in part.output ? part.output.error : null;

  return (
    <div className="rounded-lg border bg-muted/25 p-3">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="flex items-start gap-2">
          <span className="grid size-8 shrink-0 place-items-center rounded-md border bg-background">
            <GitForkIcon className="size-4" />
          </span>
          <div>
            <p className="font-medium text-sm">
              {result?.repo ?? part.input.repo}
            </p>
            <p className="mt-0.5 text-muted-foreground text-xs/relaxed">
              {errorMessage ??
                result?.description ??
                "Reading public repository metadata."}
            </p>
          </div>
        </div>
        <ToolStatusBadge state={part.state} />
      </div>
      {result ? (
        <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-2 border-t pt-3 text-muted-foreground text-xs">
          <a
            className="font-medium text-foreground underline-offset-4 hover:underline"
            href={result.url}
            rel="noreferrer"
            target="_blank"
          >
            Open repository
          </a>
          <span className="flex items-center gap-1">
            <StarIcon className="size-3" />
            {result.stars.toLocaleString()}
          </span>
          <span>{result.forks.toLocaleString()} forks</span>
          <span>{result.openIssues.toLocaleString()} open issues</span>
          <span>{result.language}</span>
        </div>
      ) : null}
    </div>
  );
}

function AnsweredAskUserCard({ part }: { part: ProjectedAskUserPart }) {
  if (!part.output) {
    return null;
  }

  return (
    <div className="rounded-lg border bg-muted/25 p-3">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <MessageCircleQuestionIcon className="size-4" />
          <p className="font-medium text-sm">Clarifying answers received</p>
        </div>
        <ToolStatusBadge state={part.state} />
      </div>
      <dl className="mt-3 grid gap-2 border-t pt-3 text-xs sm:grid-cols-2">
        {part.output.map((answer) => (
          <div key={answer.question}>
            <dt className="text-muted-foreground">{answer.question}</dt>
            <dd className="mt-0.5 font-medium">{answer.answer}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}

export interface MinimalChatAgentWorkspaceProps {
  chatModel: string;
  isChatAvailable: boolean;
  nodeVersion: string;
  setupMessage: string | null;
}

export function MinimalChatAgentWorkspace({
  chatModel,
  isChatAvailable,
  nodeVersion,
  setupMessage,
}: MinimalChatAgentWorkspaceProps) {
  const {
    addToolOutput,
    clearError,
    error,
    hasMessages,
    isBusy,
    messages,
    regenerate,
    sendMessage,
    status,
    stop,
  } = useMinimalChatAgent();
  const pendingAskUserPart = findPendingAskUserPart(messages);
  const retryConversationError = useConversationErrorRetry({
    clearError,
    regenerate,
  });

  const submitAskUserOutput = async (
    part: ProjectedAskUserPart,
    output: AskUserOutput
  ) => {
    await addToolOutput({
      output,
      tool: "ask_user",
      toolCallId: part.toolCallId,
    });
  };

  return (
    <div className="grid min-h-[72svh] gap-4 lg:h-full lg:min-h-0 lg:grid-cols-[minmax(0,1fr)_19rem]">
      <Card className="min-h-[72svh] gap-0 overflow-hidden bg-background py-0 text-base text-foreground leading-normal lg:h-full lg:min-h-0">
        {isChatAvailable ? null : (
          <>
            <div className="px-4 py-3 text-muted-foreground text-xs/relaxed">
              {setupMessage}
            </div>
            <Separator />
          </>
        )}

        <Conversation className="min-h-0">
          <ConversationContent className="mx-auto flex w-full max-w-3xl flex-1 gap-6 px-4 py-6">
            {hasMessages || error ? (
              <>
                {messages.map((message) => {
                  const projection = projectMinimalChatAgentMessage(message);
                  const hasToolParts =
                    projection.askUserParts.length > 0 ||
                    projection.githubRepoParts.length > 0 ||
                    projection.webSearchParts.length > 0;

                  return (
                    <Message from={message.role} key={message.id}>
                      <MessageContent
                        className={cn(
                          "space-y-3",
                          message.role === "assistant"
                            ? "max-w-3xl"
                            : "max-w-2xl"
                        )}
                      >
                        {projection.hasReasoningSignal ? (
                          <Reasoning
                            isStreaming={
                              isBusy && message.id === messages.at(-1)?.id
                            }
                          >
                            <ReasoningTrigger />
                            <ReasoningContent>
                              {projection.reasoningText}
                            </ReasoningContent>
                          </Reasoning>
                        ) : null}
                        {projection.webSearchParts.map((part) => (
                          <WebSearchCard key={part.toolCallId} part={part} />
                        ))}
                        {projection.githubRepoParts.map((part) => (
                          <GithubRepoCard key={part.toolCallId} part={part} />
                        ))}
                        {projection.askUserParts.map((part) => (
                          <AnsweredAskUserCard
                            key={part.toolCallId}
                            part={part}
                          />
                        ))}
                        {projection.text ? (
                          <MessageResponse>{projection.text}</MessageResponse>
                        ) : null}
                        {projection.sourceUrlParts.length > 0 ? (
                          <Sources>
                            <SourcesTrigger
                              count={projection.sourceUrlParts.length}
                            />
                            <SourcesContent>
                              {projection.sourceUrlParts.map((source) => (
                                <Source
                                  href={source.url}
                                  key={source.sourceId}
                                  title={source.title ?? source.url}
                                />
                              ))}
                            </SourcesContent>
                          </Sources>
                        ) : null}
                        {projection.text || hasToolParts ? null : (
                          <p className="text-muted-foreground text-sm">
                            Waiting for visible output.
                          </p>
                        )}
                      </MessageContent>
                    </Message>
                  );
                })}
                {pendingAskUserPart ? (
                  <AskUserCard
                    disabled={isBusy}
                    input={pendingAskUserPart.input}
                    onSubmit={(output) =>
                      submitAskUserOutput(pendingAskUserPart, output)
                    }
                  />
                ) : null}
                {error ? (
                  <ConversationErrorMessage
                    error={error}
                    isRetryDisabled={isBusy || !isChatAvailable}
                    onRetry={retryConversationError}
                  />
                ) : null}
              </>
            ) : (
              <ConversationEmptyState
                description="Ask for live information, inspect a public GitHub repository, or let the agent pause for structured clarification."
                icon={<WorkflowIcon className="size-5" />}
                title="One chat, three tool boundaries"
              />
            )}
          </ConversationContent>
          <ConversationScrollButton />
        </Conversation>

        <Separator />
        <div className="px-4 py-4">
          <div className="mx-auto w-full max-w-3xl">
            <PromptInput onSubmit={({ text }) => sendMessage({ text })}>
              <PromptInputBody>
                <PromptInputTextarea
                  disabled={
                    !isChatAvailable || isBusy || Boolean(pendingAskUserPart)
                  }
                  placeholder={
                    pendingAskUserPart
                      ? "Answer the questions above to continue."
                      : "Ask the agent to search, inspect a repository, or clarify a decision."
                  }
                />
              </PromptInputBody>
              <Separator className="mt-3" />
              <PromptInputFooter className="flex items-center justify-between gap-3 px-3 py-3">
                <div className="flex flex-wrap items-center gap-2">
                  <Badge variant="outline">OpenAI hosted search</Badge>
                  <Badge variant="outline">GitHub REST</Badge>
                  <Badge variant="outline">HITL</Badge>
                </div>
                <div className="flex items-center gap-2">
                  {isBusy ? (
                    <Button
                      onClick={stop}
                      size="sm"
                      type="button"
                      variant="outline"
                    >
                      <SquareIcon className="size-3.5" />
                      Stop
                    </Button>
                  ) : null}
                  {hasMessages && !pendingAskUserPart ? (
                    <Button
                      onClick={() => regenerate()}
                      size="sm"
                      type="button"
                      variant="outline"
                    >
                      <RefreshCwIcon className="size-3.5" />
                      Retry
                    </Button>
                  ) : null}
                  <PromptInputSubmit
                    disabled={!isChatAvailable || Boolean(pendingAskUserPart)}
                    status={status}
                  />
                </div>
              </PromptInputFooter>
            </PromptInput>

            {hasMessages ? null : (
              <div className="mt-3 grid gap-2 md:grid-cols-3">
                {samplePrompts.map((prompt) => (
                  <Button
                    className="h-auto min-h-16 justify-start whitespace-normal px-3 py-2 text-left text-xs/relaxed"
                    disabled={!isChatAvailable || isBusy}
                    key={prompt}
                    onClick={() => sendMessage({ text: prompt })}
                    type="button"
                    variant="outline"
                  >
                    <BotIcon className="size-3.5 shrink-0" />
                    {prompt}
                  </Button>
                ))}
              </div>
            )}
          </div>
        </div>
      </Card>

      <Card className="bg-background p-4 text-base text-foreground leading-normal lg:min-h-0 lg:overflow-y-auto lg:pr-24">
        <div className="space-y-5">
          <div>
            <p className="font-heading text-muted-foreground text-xs uppercase tracking-[0.16em]">
              Minimal agent loop
            </p>
            <p className="mt-2 text-muted-foreground text-sm/relaxed">
              The model chooses tools, receives structured results, and keeps
              streaming until the task is complete or a human answer is needed.
            </p>
          </div>
          <Separator />
          <div className="space-y-3">
            <div className="flex items-start gap-2">
              <SearchIcon className="mt-0.5 size-4 shrink-0" />
              <div>
                <p className="font-medium text-sm">web_search</p>
                <p className="text-muted-foreground text-xs/relaxed">
                  OpenAI hosted retrieval with streamed source parts.
                </p>
              </div>
            </div>
            <div className="flex items-start gap-2">
              <GitForkIcon className="mt-0.5 size-4 shrink-0" />
              <div>
                <p className="font-medium text-sm">github_repo</p>
                <p className="text-muted-foreground text-xs/relaxed">
                  A server tool that reads public repository metadata.
                </p>
              </div>
            </div>
            <div className="flex items-start gap-2">
              <MessageCircleQuestionIcon className="mt-0.5 size-4 shrink-0" />
              <div>
                <p className="font-medium text-sm">ask_user</p>
                <p className="text-muted-foreground text-xs/relaxed">
                  An unexecuted tool whose output comes from the questionnaire
                  UI.
                </p>
              </div>
            </div>
          </div>
          <Separator />
          <div>
            <p className="font-heading text-muted-foreground text-xs uppercase tracking-[0.16em]">
              Runtime
            </p>
            <p className="mt-1 font-medium text-sm">{nodeVersion}</p>
            <p className="mt-1 break-all font-mono text-muted-foreground text-xs">
              {chatModel}
            </p>
          </div>
        </div>
      </Card>
    </div>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { MessageCircleQuestionIcon, SendIcon } from "lucide-react";
import { useMemo, useState } from "react";

import type { AskUserInput, AskUserOutput } from "@/lib/minimal-chat-agent/tools";
import { buildAskUserOutput } from "@/components/minimal-chat-agent/ask-user-state";

interface AskUserCardProps {
  disabled?: boolean;
  input: AskUserInput;
  onSubmit: (output: AskUserOutput) => Promise<void> | void;
}

export function AskUserCard({
  disabled = false,
  input,
  onSubmit,
}: AskUserCardProps) {
  const [answers, setAnswers] = useState<Record<number, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const output = useMemo(
    () => buildAskUserOutput(input, answers),
    [answers, input]
  );

  return (
    <Card className="border-primary/25 bg-primary/[0.03] shadow-none">
      <CardHeader className="gap-2 pb-3">
        <div className="flex items-center justify-between gap-3">
          <CardTitle className="flex items-center gap-2 font-medium text-base">
            <MessageCircleQuestionIcon className="size-4 text-primary" />A quick
            decision from you
          </CardTitle>
          <Badge variant="outline">Human in the loop</Badge>
        </div>
        <p className="text-muted-foreground text-sm/relaxed">
          The agent paused instead of guessing. Answer every question to
          continue the same tool loop.
        </p>
      </CardHeader>
      <CardContent>
        <form
          className="space-y-5"
          onSubmit={(event) => {
            event.preventDefault();

            if (!output || isSubmitting) {
              return;
            }

            setIsSubmitting(true);
            Promise.resolve(onSubmit(output)).finally(() => {
              setIsSubmitting(false);
            });
          }}
        >
          {input.questions.map((question, index) => (
            <fieldset className="space-y-3" key={question.question}>
              <legend className="font-medium text-sm">
                <span className="mr-2 font-mono text-muted-foreground text-xs">
                  {String(index + 1).padStart(2, "0")}
                </span>
                {question.question}
              </legend>
              <div className="grid gap-2 sm:grid-cols-3">
                {question.choices.map((choice) => {
                  const isSelected = answers[index] === choice;

                  return (
                    <Button
                      aria-pressed={isSelected}
                      className="h-auto min-h-10 justify-start whitespace-normal text-left"
                      disabled={disabled || isSubmitting}
                      key={choice}
                      onClick={() => {
                        setAnswers((current) => ({
                          ...current,
                          [index]: choice,
                        }));
                      }}
                      type="button"
                      variant={isSelected ? "secondary" : "outline"}
                    >
                      {choice}
                    </Button>
                  );
                })}
              </div>
              <Input
                aria-label={`Custom answer for: ${question.question}`}
                disabled={disabled || isSubmitting}
                onChange={(event) => {
                  setAnswers((current) => ({
                    ...current,
                    [index]: event.target.value,
                  }));
                }}
                placeholder="Or type a custom answer"
                value={
                  question.choices.includes(answers[index] ?? "")
                    ? ""
                    : (answers[index] ?? "")
                }
              />
            </fieldset>
          ))}
          <Button
            className="w-full sm:w-auto"
            disabled={disabled || isSubmitting || !output}
            type="submit"
          >
            <SendIcon className="size-4" />
            {isSubmitting ? "Continuing…" : "Continue agent run"}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

import type { AskUserInput, AskUserOutput } from "@/lib/minimal-chat-agent/tools";

export function buildAskUserOutput(
  input: AskUserInput,
  answers: Record<number, string>
): AskUserOutput | null {
  const output = input.questions.map((item, index) => ({
    answer: answers[index]?.trim() ?? "",
    question: item.question,
  }));

  if (output.some((item) => item.answer.length === 0)) {
    return null;
  }

  return output;
}

import {
  type AskUserInput,
  type AskUserOutput,
  askUserInputSchema,
  askUserOutputSchema,
  type GithubRepoInput,
  type GithubRepoOutput,
  githubRepoInputSchema,
  githubRepoOutputSchema,
} from "@/lib/minimal-chat-agent/tools";
import type { MinimalChatAgentUIMessage } from "@/lib/minimal-chat-agent/types";

type MessagePart = MinimalChatAgentUIMessage["parts"][number];

export interface ProjectedAskUserPart {
  input: AskUserInput;
  output?: AskUserOutput;
  state: string;
  toolCallId: string;
  type: "tool-ask_user";
}

export interface ProjectedGithubRepoPart {
  input: GithubRepoInput;
  output?: GithubRepoOutput;
  state: string;
  toolCallId: string;
  type: "tool-github_repo";
}

export interface ProjectedWebSearchPart {
  input: unknown;
  output?: unknown;
  state: string;
  toolCallId: string;
  type: "tool-web_search";
}

export interface ProjectedSourceUrlPart {
  sourceId: string;
  title?: string;
  type: "source-url";
  url: string;
}

function getText(part: MessagePart) {
  return part.type === "text" && part.text.trim().length > 0
    ? part.text.trim()
    : null;
}

function getReasoningText(part: MessagePart) {
  return part.type === "reasoning" ? part.text.trim() : null;
}

function projectAskUserPart(part: MessagePart): ProjectedAskUserPart | null {
  if (part.type !== "tool-ask_user") {
    return null;
  }

  const parsedInput = askUserInputSchema.safeParse(part.input);

  if (!parsedInput.success) {
    return null;
  }

  const parsedOutput =
    "output" in part ? askUserOutputSchema.safeParse(part.output) : null;

  return {
    input: parsedInput.data,
    output: parsedOutput?.success ? parsedOutput.data : undefined,
    state: part.state,
    toolCallId: part.toolCallId,
    type: "tool-ask_user",
  };
}

function projectGithubRepoPart(
  part: MessagePart
): ProjectedGithubRepoPart | null {
  if (part.type !== "tool-github_repo") {
    return null;
  }

  const parsedInput = githubRepoInputSchema.safeParse(part.input);

  if (!parsedInput.success) {
    return null;
  }

  const parsedOutput =
    "output" in part ? githubRepoOutputSchema.safeParse(part.output) : null;

  return {
    input: parsedInput.data,
    output: parsedOutput?.success ? parsedOutput.data : undefined,
    state: part.state,
    toolCallId: part.toolCallId,
    type: "tool-github_repo",
  };
}

function projectWebSearchPart(
  part: MessagePart
): ProjectedWebSearchPart | null {
  if (part.type !== "tool-web_search") {
    return null;
  }

  return {
    input: part.input,
    output: "output" in part ? part.output : undefined,
    state: part.state,
    toolCallId: part.toolCallId,
    type: "tool-web_search",
  };
}

function projectSourceUrlPart(
  part: MessagePart
): ProjectedSourceUrlPart | null {
  if (part.type !== "source-url") {
    return null;
  }

  return {
    sourceId: part.sourceId,
    title: part.title,
    type: "source-url",
    url: part.url,
  };
}

export function projectMinimalChatAgentMessage(
  message: MinimalChatAgentUIMessage
) {
  const textParts = message.parts.map(getText).filter((text) => text !== null);
  const reasoningParts = message.parts
    .map(getReasoningText)
    .filter((text) => text !== null);
  const askUserParts = message.parts
    .map(projectAskUserPart)
    .filter((part) => part !== null);
  const githubRepoParts = message.parts
    .map(projectGithubRepoPart)
    .filter((part) => part !== null);
  const webSearchParts = message.parts
    .map(projectWebSearchPart)
    .filter((part) => part !== null);
  const seenSourceUrls = new Set<string>();
  const sourceUrlParts = message.parts
    .map(projectSourceUrlPart)
    .filter((part): part is ProjectedSourceUrlPart => {
      if (!part || seenSourceUrls.has(part.url)) {
        return false;
      }

      seenSourceUrls.add(part.url);
      return true;
    });

  return {
    askUserParts,
    githubRepoParts,
    hasReasoningSignal: reasoningParts.length > 0,
    reasoningText: reasoningParts.join("\n\n"),
    sourceUrlParts,
    text: textParts.join("\n\n"),
    webSearchParts,
  };
}

export function findPendingAskUserPart(
  messages: MinimalChatAgentUIMessage[]
): ProjectedAskUserPart | null {
  for (
    let messageIndex = messages.length - 1;
    messageIndex >= 0;
    messageIndex--
  ) {
    const message = messages[messageIndex];

    if (!message) {
      continue;
    }

    for (
      let partIndex = message.parts.length - 1;
      partIndex >= 0;
      partIndex--
    ) {
      const part = message.parts[partIndex];
      const askUserPart = part ? projectAskUserPart(part) : null;

      if (askUserPart?.state === "input-available") {
        return askUserPart;
      }
    }
  }

  return null;
}

