export type GithubRepoOutput = z.infer<typeof githubRepoOutputSchema>;

export interface GithubRepositorySummary {
  description: string;
  forks: number;
  language: string;
  openIssues: number;
  repo: string;
  stars: number;
  url: string;
}

export interface GithubRepositoryError {
  error: string;
}

interface GithubLookupDependencies {
  abortSignal?: AbortSignal;
  fetch?: typeof fetch;
}

export function parseGithubRepositoryName(repo: string) {
  const normalizedRepo = repo.trim();

  if (!githubRepositoryPattern.test(normalizedRepo)) {
    throw new Error('Expected a GitHub repository in "owner/name" format.');
  }

  return normalizedRepo;
}

function getRequestSignal(abortSignal?: AbortSignal) {
  const timeoutSignal = AbortSignal.timeout(githubRequestTimeoutMs);

  return abortSignal
    ? AbortSignal.any([abortSignal, timeoutSignal])
    : timeoutSignal;
}

export async function lookupGithubRepository(
  repo: string,
  dependencies: GithubLookupDependencies = {}
): Promise<GithubRepositorySummary | GithubRepositoryError> {
  const normalizedRepo = parseGithubRepositoryName(repo);
  const fetchImplementation = dependencies.fetch ?? fetch;

  try {
    const response = await fetchImplementation(
      `https://api.github.com/repos/${normalizedRepo}`,
      {
        headers: {
          accept: "application/vnd.github+json",
          "x-github-api-version": githubApiVersion,
        },
        signal: getRequestSignal(dependencies.abortSignal),
      }
    );

    if (!response.ok) {
      return {
        error: `Could not find public GitHub repository ${normalizedRepo}.`,
      };
    }

    const data = (await response.json()) as Record<string, unknown>;
    const resolvedRepo =
      typeof data.full_name === "string"
        ? parseGithubRepositoryName(data.full_name)
        : normalizedRepo;

    return {
      description: typeof data.description === "string" ? data.description : "",
      forks: Number(data.forks_count ?? 0),
      language: typeof data.language === "string" ? data.language : "Unknown",
      openIssues: Number(data.open_issues_count ?? 0),
      repo: resolvedRepo,
      stars: Number(data.stargazers_count ?? 0),
      url: `https://github.com/${resolvedRepo}`,
    };
  } catch {
    return {
      error: `Could not reach GitHub for ${normalizedRepo}.`,
    };
  }
}

export const githubRepoTool = tool({
  description:
    "Get public stats for a GitHub repository: stars, forks, open issues, language, and description.",
  execute: ({ repo }, { abortSignal }) =>
    lookupGithubRepository(repo, { abortSignal }),
  inputSchema: githubRepoInputSchema,
  outputSchema: githubRepoOutputSchema,
});

export const askUserTool = tool({
  description:
    "Ask the user clarifying questions when their request is ambiguous. Provide one or more questions, each with exactly three short, distinct answer choices. The user can also answer in their own words.",
  inputSchema: askUserInputSchema,
  outputSchema: askUserOutputSchema,
});

interface WebSearchProvider<TWebSearchTool> {
  webSearch: (options: { searchContextSize: "medium" }) => TWebSearchTool;
}

export function createMinimalChatAgentTools<TWebSearchTool>(
  provider: WebSearchProvider<TWebSearchTool>
) {
  return {
    web_search: provider.webSearch({ searchContextSize: "medium" }),
    github_repo: githubRepoTool,
    ask_user: askUserTool,
  };
}

import { createOpenAI } from "@ai-sdk/openai";
import {
  convertToModelMessages,
  stepCountIs,
  streamText,
  type UIMessage,
} from "ai";

import {
  getMinimalChatAgentConfig,
  getMinimalChatAgentEnv,
  type MinimalChatAgentEnv,
} from "./env";
import { createMinimalChatAgentTools } from "./tools";

const systemPrompt = [
  "You are Minimal Chat Agent, a compact example of a useful tool-aware assistant.",
  "Answer directly when durable reasoning is enough.",
  "Use web_search when current public information materially improves the answer.",
  'Use github_repo for public repository facts after identifying an exact "owner/name" coordinate.',
  "Use ask_user instead of guessing when the request is ambiguous, consequential, or missing preferences needed for a useful recommendation.",
  "After the user answers ask_user, continue the original task using those answers.",
  "Keep questions and final answers concise.",
].join(" ");

const trailingSlashPattern = /\/$/;
const v3AiSuffixPattern = /\/v3\/ai$/;

function resolveOpenAICompatibleBaseURL(baseURL: string) {
  const normalizedBaseURL = baseURL.replace(trailingSlashPattern, "");

  if (normalizedBaseURL.endsWith("/v1")) {
    return normalizedBaseURL;
  }

  if (normalizedBaseURL.endsWith("/v3/ai")) {
    return normalizedBaseURL.replace(v3AiSuffixPattern, "/v1");
  }

  throw new Error(
    `Minimal Chat Agent expects AI_GATEWAY_BASE_URL to end with /v3/ai or /v1. Received: ${baseURL}`
  );
}

export async function streamMinimalChatAgent(
  messages: UIMessage[],
  env: MinimalChatAgentEnv = getMinimalChatAgentEnv(),
  abortSignal?: AbortSignal
) {
  const { apiKey, baseURL, chatModel } = getMinimalChatAgentConfig(env);
  const openai = createOpenAI({
    apiKey,
    baseURL: resolveOpenAICompatibleBaseURL(baseURL),
    name: "gateway-openai",
  });
  const runId = crypto.randomUUID();
  const startedAt = Date.now();
  const result = streamText({
    abortSignal,
    experimental_telemetry: {
      functionId: "minimal-chat-agent.run",
      isEnabled: true,
      metadata: {
        demo: "minimal-chat-agent",
        runId,
      },
      recordInputs: true,
      recordOutputs: true,
    },
    maxOutputTokens: 4096,
    messages: await convertToModelMessages(messages),
    model: openai(chatModel),
    stopWhen: stepCountIs(5),
    system: systemPrompt,
    tools: createMinimalChatAgentTools(openai.tools),
  });

  return result.toUIMessageStreamResponse({
    messageMetadata: ({ part }) => {
      if (part.type === "start") {
        return {
          model: chatModel,
          runId,
          startedAt,
        };
      }

      if (part.type === "finish") {
        return {
          finishReason: part.finishReason,
          finishedAt: Date.now(),
          model: chatModel,
          runId,
          startedAt,
          totalUsage: part.totalUsage,
        };
      }

      return;
    },
    onError: () => "Minimal Chat Agent could not complete this turn.",
    originalMessages: messages,
    sendReasoning: true,
    sendSources: true,
  });
}

import { type UIMessage, validateUIMessages } from "ai";

import {
  getMinimalChatAgentEnv,
  getMinimalChatAgentSetupState,
  type MinimalChatAgentEnv,
} from "./env";

interface MinimalChatAgentRequestBody {
  messages?: UIMessage[];
}

export interface MinimalChatAgentRuntimeState {
  chatModel: string;
  isChatAvailable: boolean;
  nodeVersion: string;
  setupMessage: string | null;
  statusLabel: "Ready" | "Setup required";
}

interface MinimalChatAgentRequestDependencies {
  streamMinimalChatAgent: (
    messages: UIMessage[],
    env: MinimalChatAgentEnv,
    abortSignal: AbortSignal
  ) => Promise<Response>;
}

const invalidMessagesError = 'Expected a JSON body with a "messages" array.';
const invalidUiMessagesError =
  'Expected each "messages" entry to match the UIMessage format.';
const malformedJsonError = "Expected a valid JSON request body.";

export function getMinimalChatAgentRuntimeState(
  env: MinimalChatAgentEnv = getMinimalChatAgentEnv()
): MinimalChatAgentRuntimeState {
  const setup = getMinimalChatAgentSetupState(env);

  return {
    chatModel: setup.config.chatModel,
    isChatAvailable: setup.isReady,
    nodeVersion: setup.nodeVersion,
    setupMessage: setup.issues.length > 0 ? setup.issues.join(" ") : null,
    statusLabel: setup.isReady ? "Ready" : "Setup required",
  };
}

async function readMinimalChatAgentMessages(body: unknown) {
  const { messages } = (body ?? {}) as MinimalChatAgentRequestBody;

  if (!Array.isArray(messages)) {
    throw new Error(invalidMessagesError);
  }

  try {
    return await validateUIMessages({ messages });
  } catch {
    throw new Error(invalidUiMessagesError);
  }
}

async function streamMinimalChatAgentFromRuntime(
  messages: UIMessage[],
  env: MinimalChatAgentEnv,
  abortSignal: AbortSignal
) {
  const { streamMinimalChatAgent } = await import("./chat");

  return streamMinimalChatAgent(messages, env, abortSignal);
}

export async function handleMinimalChatAgentRequest(
  request: Request,
  env: MinimalChatAgentEnv = getMinimalChatAgentEnv(),
  dependencies: MinimalChatAgentRequestDependencies = {
    streamMinimalChatAgent: streamMinimalChatAgentFromRuntime,
  }
) {
  const runtimeState = getMinimalChatAgentRuntimeState(env);

  if (!runtimeState.isChatAvailable) {
    return Response.json(
      {
        error: runtimeState.setupMessage,
      },
      { status: 500 }
    );
  }

  let messages: UIMessage[];

  try {
    messages = await readMinimalChatAgentMessages(await request.json());
  } catch (error) {
    if (error instanceof SyntaxError) {
      return Response.json({ error: malformedJsonError }, { status: 400 });
    }

    if (
      error instanceof Error &&
      [invalidMessagesError, invalidUiMessagesError].includes(error.message)
    ) {
      return Response.json({ error: error.message }, { status: 400 });
    }

    throw error;
  }

  return dependencies.streamMinimalChatAgent(messages, env, request.signal);
}
